<?php
declare(strict_types=1);

function render_paystack_checkout(): void {
    $lines = cart_lines();
    if (!$lines) { flash('notice', 'Your bag is empty.'); redirect('index.php?page=shop'); }
    try { $quote = payment_cart_quote($lines); $problem = null; } catch (Throwable $error) { $quote = null; $problem = $error->getMessage(); }
    render_header('Secure checkout'); ?>
    <section class="checkout-header"><a href="index.php?page=cart">&larr; Back to bag</a><h1>Secure <i>checkout.</i></h1><p>Review the final payment amount, then continue securely with Paystack.</p></section>
    <section class="checkout-layout"><form method="post" class="checkout-form"><?=csrf_input()?><input type="hidden" name="action" value="place_order"><h2>Customer information</h2><div class="form-grid"><label>Full name<input required name="full_name" autocomplete="name"></label><label>Phone number<input required name="phone" autocomplete="tel" type="tel"></label><label class="full">Email address <small>(required by Paystack)</small><input required name="email" autocomplete="email" type="email"></label></div><h2>Delivery information</h2><div class="form-grid"><label>State<input required name="state" autocomplete="address-level1"></label><label>City / Town<input required name="city" autocomplete="address-level2"></label><label class="full">Full delivery address<textarea required name="address" autocomplete="street-address" rows="3"></textarea></label><label class="full">Landmark or delivery instructions <small>(optional)</small><input name="landmark"></label></div><?php if ($problem): ?><div class="payment-alert"><b>Payment setup needed</b><br><?=h($problem)?></div><a class="button wide" href="index.php?page=cart">Back to bag</a><?php else: ?><button class="button wide">Continue to Paystack <span>&rarr;</span></button><?php endif; ?><p class="payment-note">Your card or bank details are entered only on Paystack’s secure payment page.</p></form>
    <aside class="order-summary checkout-summary"><p class="eyebrow">payment summary</p><?php foreach($lines as $line):?><div class="summary-product"><img src="<?=h($line['image'])?>" alt=""><span><?=h($line['name'])?><small>&times; <?=$line['quantity']?></small></span><b><?=payment_money_kobo(payment_decimal_to_kobo($line['discount_price'] !== null ? (string)$line['discount_price'] : (string)$line['price']) * (int)$line['quantity'])?></b></div><?php endforeach; if($quote):?><hr><div><span>Items / recipient amount</span><b><?=payment_money_kobo($quote['base_kobo'])?></b></div><div><span>Service charge</span><b><?=payment_money_kobo($quote['service_kobo'])?></b></div><div><span>Payment processing</span><b><?=payment_money_kobo($quote['paystack_kobo'])?></b></div><hr><div class="grand"><span>Total to pay</span><b><?=payment_money_kobo($quote['gross_kobo'])?></b></div><p class="payment-note">The payment and service charges cover secure processing. <?=h($quote['recipient']['name'])?> is expected to receive <?=payment_money_kobo($quote['expected_net_kobo'])?>.</p><?php endif;?></aside></section>
    <?php render_footer();
}
